mapper.select:
SELECT S.SHEET_NAME, L.ROW_NO, L.COLUMN_NO, L.ORG_VALUE, L.MOD_VALUE,
       L.INPUT_DATETIME AS CHANGED_AT, L.INPUT_USER AS CHANGED_USER
  FROM wo_cell_change_log L
  JOIN wo_workbook_sheet_line S ON S.SHEET_SEQ = L.SHEET_SEQ
 WHERE S.WORKBOOK_SEQ = #{workbookSeq}
   AND L.INPUT_DATETIME >= #{fromAt}
   AND L.INPUT_DATETIME <= #{toAt}
   AND L.DEL_DATETIME IS NULL
 ORDER BY L.LOG_SEQ DESC
 FETCH FIRST #{limit} ROWS ONLY

SELECT CHANGE_TYPE, ORG_VALUE, MOD_VALUE,
       INPUT_DATETIME AS CHANGED_AT, INPUT_USER AS CHANGED_USER
  FROM wo_cell_change_log
 WHERE SHEET_SEQ = #{sheetSeq}
   AND ROW_NO    = #{rowNo}
   AND COLUMN_NO = #{columnNo}
   AND DEL_DATETIME IS NULL
 ORDER BY LOG_SEQ DESC
 FETCH FIRST #{limit} ROWS ONLY
